-- Preserve immutable history identity; permit only proved saved replacements.
DROP TRIGGER kids_history_message_immutable;
--> statement-breakpoint
CREATE TRIGGER kids_history_message_immutable BEFORE UPDATE ON kids_hosted_history_messages
WHEN NEW.sequence IS NOT OLD.sequence OR NEW.page_id IS NOT OLD.page_id OR NEW.binding_id IS NOT OLD.binding_id OR NEW.binding_revision IS NOT OLD.binding_revision OR NEW.epoch IS NOT OLD.epoch OR NEW.chat_id IS NOT OLD.chat_id OR NEW.message_id IS NOT OLD.message_id OR NEW.body_hash IS NOT OLD.body_hash OR NEW.fingerprint IS NOT OLD.fingerprint OR NEW.message_millis IS NOT OLD.message_millis
 OR NOT(OLD.raw_body IS NOT NULL AND OLD.consumed_at IS NULL AND NEW.raw_body IS NULL AND NEW.raw_bytes=0 AND NEW.consumed_at IS NOT NULL AND (EXISTS(SELECT 1 FROM kids_hosted_history_heads h WHERE h.binding_id=OLD.binding_id AND h.chat_id=OLD.chat_id AND h.message_id=OLD.message_id AND h.message_sequence=OLD.sequence AND h.body_hash=OLD.body_hash AND h.fingerprint=OLD.fingerprint) OR EXISTS(SELECT 1 FROM kids_hosted_message_heads h JOIN kids_hosted_bindings b ON b.id=h.binding_id JOIN kids_source_records r ON r.owner_user_id=b.owner_user_id AND r.workspace_id=b.workspace_id AND r.chat_id=h.chat_id AND r.message_id=h.message_id AND r.fingerprint=h.fingerprint JOIN kids_hosted_history_pages p ON p.id=OLD.page_id AND p.owner_user_id=b.owner_user_id AND p.workspace_id=b.workspace_id AND p.status='committed' AND p.response_hash IS NOT NULL WHERE h.binding_id=OLD.binding_id AND h.chat_id=OLD.chat_id AND h.message_id=OLD.message_id AND NOT EXISTS(SELECT 1 FROM kids_hosted_history_batch_members m JOIN kids_hosted_batches lease ON lease.id=m.batch_id WHERE m.message_sequence=OLD.sequence AND lease.source_kind='history' AND lease.status='ready')) OR EXISTS(SELECT 1 FROM kids_hosted_bindings b JOIN kids_hosted_removals r ON r.owner_user_id=b.owner_user_id AND r.workspace_id=b.workspace_id,json_each(r.bindings_json) x WHERE b.id=OLD.binding_id AND b.active=0 AND b.removed_at IS NOT NULL AND r.status='completed' AND json_extract(x.value,'$.id')=b.id)))
BEGIN SELECT RAISE(ABORT,'KIDS_HISTORY_MESSAGE_IMMUTABLE'); END;
